WITH src AS (SELECT * FROM subscriptions WHERE MONTH(start_date) IN (2, 6, 10) AND status <> 'CANCELLED'), agg AS (SELECT MONTH(end_date) AS end_month, CASE WHEN status IN ('CANCELLED', 'EXPIRED') THEN 'core' ELSE 'other' END AS status_group, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values, SORT_ARRAY(COLLECT_SET(status)) AS status_list FROM src GROUP BY MONTH(end_date), CASE WHEN status IN ('CANCELLED', 'EXPIRED') THEN 'core' ELSE 'other' END) SELECT end_month, status_group, status_values, status_list FROM agg ORDER BY end_month DESC;
